/**
 * Compute the changes that turn `base` into `side`, using an LCS over
 * whole lines with exact string equality. Ties in the LCS are broken by
 * preferring the earliest matches, walking from the start and advancing
 * whichever side keeps the longer remaining subsequence available,
 * preferring to advance the base on a tie.
 * @param {string[]} base
 * @param {string[]} side
 * @returns {{baseStart:number, baseEnd:number, lines:string[]}[]}
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length
  const width = m + 1
  const dp = new Int32Array((n + 1) * width)

  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const idx = i * width + j
      if (base[i] === side[j]) {
        dp[idx] = dp[(i + 1) * width + (j + 1)] + 1
      } else {
        const advBase = dp[(i + 1) * width + j]
        const advSide = dp[i * width + (j + 1)]
        dp[idx] = advBase >= advSide ? advBase : advSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advBase = dp[(i + 1) * width + j]
      const advSide = dp[i * width + (j + 1)]
      if (advBase >= advSide) {
        i++
      } else {
        j++
      }
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevI, baseEnd: mi, lines: side.slice(prevJ, mj) })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, lines: side.slice(prevJ, m) })
  }

  return changes
}
"}

