 * Combine the changes from each side against the base into regions and
 * resolve each region to stable, mine, theirs, both or conflict.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Reconstruct a side's lines over a base range [start, end), given only
 * that side's changes overlapping the range. Gaps between changes, and
 * the padding out to the region boundaries, are filled with base lines.
 * @param {{baseStart:number, baseEnd:number, lines:string[]}[]} changes
 * @param {string[]} base
 * @param {number} start
 * @param {number} end
 */
function buildSideLines(changes, base, start, end) {
  if (changes.length === 0) {
    return base.slice(start, end)
  }
  const sideStart = changes[0].baseStart
  let sideEnd = changes[0].baseEnd
  for (const c of changes) {
    if (c.baseEnd > sideEnd) sideEnd = c.baseEnd
  }

  const result = []
  result.push(...base.slice(start, sideStart))
  let pos = sideStart
  for (const c of changes) {
    result.push(...base.slice(pos, c.baseStart))
    result.push(...c.lines)
    pos = c.baseEnd
  }
  result.push(...base.slice(pos, sideEnd))
  result.push(...base.slice(sideEnd, end))
  return result
}

/**
 * Build the ordered list of regions describing how to merge `mine` and
 * `theirs` against `base`.
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 */
export function buildRegions(mine, base, theirs) {
  const changesMine = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const changesTheirs = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))
  const all = [...changesMine, ...changesTheirs].sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let lastEnd = 0
  let idx = 0
  while (idx < all.length) {
    let regionStart = all[idx].baseStart
    let regionEnd = all[idx].baseEnd
    if (regionStart > lastEnd) {
      regions.push({ kind: 'stable', lines: base.slice(lastEnd, regionStart) })
    }
    const touching = [all[idx]]
    idx++
    while (idx < all.length && all[idx].baseStart <= regionEnd) {
      touching.push(all[idx])
      if (all[idx].baseEnd > regionEnd) regionEnd = all[idx].baseEnd
      idx++
    }

    const mineChanges = touching.filter(c => c.side === 'mine')
    const theirsChanges = touching.filter(c => c.side === 'theirs')
    const mineLines = buildSideLines(mineChanges, base, regionStart, regionEnd)
    const theirsLines = buildSideLines(theirsChanges, base, regionStart, regionEnd)
    const baseLines = base.slice(regionStart, regionEnd)

    regions.push(classify(mineLines, baseLines, theirsLines, mineChanges.length > 0, theirsChanges.length > 0))

    lastEnd = regionEnd
  }
  if (lastEnd < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(lastEnd, base.length) })
  }

  return regions
}

function classify(mineLines, baseLines, theirsLines, mineChanged, theirsChanged) {
  if (arraysEqual(mineLines, theirsLines)) {
    if (mineChanged && theirsChanged) {
      return { kind: 'both', lines: mineLines }
    }
    return { kind: mineChanged ? 'mine' : 'theirs', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { kind: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { kind: 'mine', lines: mineLines }
  }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}
"}

